def is_prime(n):
    if n < 2:
        return False
    d = 2
    while d * d <= n:
        if n % d == 0:
            return False
        d += 1
    return True

streak = 0
for n in range(100):
    value = n * n + n + 41
    if not is_prime(value):
        print(f"n = {n}: {value} is NOT prime ({value} = 41 x {value // 41})")
        break
    streak += 1
print(f"prime for every n from 0 to {streak - 1}: {streak} cases in a row")

# Claim to test: "if p is prime, then 2^p - 1 is prime"
def smallest_factor(m):
    d = 2
    while d * d <= m:
        if m % d == 0:
            return d
        d += 1
    return None   # no factor found, so m is prime

for p in [2, 3, 5, 7, 11, 13]:
    m = 2 ** p - 1
    f = smallest_factor(m)
    if f is None:
        print(f"p = {p:>2}: 2^p - 1 = {m} is prime")
    else:
        print(f"p = {p:>2}: 2^p - 1 = {m} = {f} x {m // f}, NOT prime")
